<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $title }} · Administración Adanis</title><style>:root{--navy:#0d1b2a;--blue:#1769aa;--ink:#17212b;--muted:#607083;--line:#dbe4ee;--bg:#f6f8fb;--red:#b42318}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:linear-gradient(135deg,#edf5fb,#f6f8fb);color:var(--ink);font-family:Inter,system-ui,sans-serif}.card{width:min(440px,100%);background:#fff;border:1px solid var(--line);border-radius:16px;padding:32px;box-shadow:0 15px 45px rgba(25,50,75,.12)}h1{font-size:26px;margin:5px 0 8px}.brand{font-weight:850;color:var(--navy);font-size:19px}.brand span{color:var(--blue)}p{color:var(--muted);line-height:1.5;margin:0 0 22px}label{display:block;font-size:13px;font-weight:750;margin:14px 0 6px}input{width:100%;border:1px solid #cbd8e5;border-radius:8px;padding:11px;font:inherit}.button{width:100%;margin-top:21px;border:0;border-radius:8px;background:var(--blue);color:#fff;padding:11px;font:inherit;font-weight:800;cursor:pointer}.error{color:var(--red);font-size:13px;margin-top:10px}.ok{background:#e8f2ea;color:#24653b;border-radius:8px;padding:10px;font-size:13px;margin:0 0 16px}.link{display:block;text-align:center;margin-top:18px;color:var(--blue);font-size:13px;font-weight:700;text-decoration:none}</style></head><body><main class="card"><div class="brand">Adanis <span>Administración</span></div><h1>{{ $title }}</h1><p>{{ $description }}</p>@if(session('status'))<div class="ok">{{ session('status') }}</div>@endif @if($form === 'forgot')<form method="post" action="{{ route('password.email') }}">@csrf<label for="email">Correo electrónico</label><input id="email" type="email" name="email" value="{{ old('email') }}" autocomplete="email" required autofocus>@error('email')<div class="error">{{ $message }}</div>@enderror<button class="button">Enviar enlace</button></form><a class="link" href="{{ route('login') }}">Volver a ingresar</a>@else<form method="post" action="{{ route('password.update') }}">@csrf<input type="hidden" name="token" value="{{ $token }}"><label for="email">Correo electrónico</label><input id="email" type="email" name="email" value="{{ old('email',$email) }}" autocomplete="email" required><label for="password">Nueva contraseña</label><input id="password" type="password" name="password" autocomplete="new-password" required><label for="password_confirmation">Confirmar contraseña</label><input id="password_confirmation" type="password" name="password_confirmation" autocomplete="new-password" required>@error('email')<div class="error">{{ $message }}</div>@enderror<button class="button">Guardar contraseña</button></form>@endif</main></body></html>
